<?php require_once __DIR__.'/../includes/bootstrap.php';require_customer();$title='My Orders';$s=$pdo->prepare('SELECT * FROM orders WHERE customer_id=? ORDER BY created_at DESC');$s->execute([$_SESSION['customer_id']]);$rows=$s->fetchAll();require __DIR__.'/../includes/header.php';?><div class="section-head"><div><span class="eyebrow">MY ORDERS</span><h1>Orders & delivery tracking</h1></div></div><div class="order-cards"><?php foreach($rows as $o): ?><a class="order-card order-card-wide" href="/customer/order.php?id=<?=$o['order_id']?>"><div><strong><?=e($o['order_number'])?></strong><small>Placed <?=e($o['created_at'])?></small></div><span class="status-pill <?=e(order_status_class($o['status']))?>"><?=e(order_status_label($o['status']))?></span><strong><?=money((float)$o['total_amount'])?></strong><span>Track order →</span></a><?php endforeach; ?><?php if(!$rows): ?><div class="empty"><h2>No orders yet</h2><a class="btn primary" href="/">Shop now</a></div><?php endif; ?></div><?php require __DIR__.'/../includes/footer.php'; ?>
